Class means separate strongly on area/luminosity/steel-type features. Next I compare closed-form classifiers (shrinkage LDA, nearest centroid, kNN) by leave-one-out accuracy to pick what the net should compute.
```python
X=np.load("train_x.npy"); y=np.load("train_y.npy"); n,d=X.shape
def lda_fit(X,y,a,prior=True):
    M=np.stack([X[y==c].mean(0) for c in range(7)])
    R=X-M[y]; S=R.T@R/(len(X)-7)
    S=(1-a)*S+a*np.trace(S)/d*np.eye(d)
    Si=np.linalg.pinv(S)
    W=M@Si; b=-0.5*np.sum(W*M,1)
    if prior: b=b+np.log(np.bincount(y,minlength=7)/len(y))
    return W,b
def loo(fn):
    ok=0
    for i in range(n):
        m=np.ones(n,bool); m[i]=False
        ok+= fn(X[m],y[m],X[i])==y[i]
    return ok/n
for a in [0.01,0.05,0.1,0.2,0.4,0.7,1.0]:
    for pr in [True,False]:
        print('lda',a,pr, loo(lambda A,B,x:(lambda W,b: np.argmax(W@x+b))(*lda_fit(A,B,a,pr))))
for k in [1,3,5,7]:
    def knn(A,B,x,k=k):
        dd=((A-x)**2).sum(1); idx=np.argsort(dd)[:k]
        return np.bincount(B[idx],minlength=7).argmax()
    print('knn',k,loo(knn))
